return ['project-id-version'=>'Lingua Forge 2.1.0','report-msgid-bugs-to'=>'https://wordpress.org/support/plugin/lingua-forge','last-translator'=>'admin','language-team'=>'Indonesian','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','pot-creation-date'=>'2026-06-01T15:14:22+00:00','po-revision-date'=>'2026-06-03 15:28+0000','x-generator'=>'Loco https://localise.biz/','x-domain'=>'lingua-forge','language'=>'id_ID','plural-forms'=>'nplurals=1; plural=0;','x-loco-version'=>'2.8.5; wp-7.0; php-8.3.31','messages'=>['"%1$s %2$s" saved.'=>'"%1$s %2$s" disimpan.','"%1$s" created. %2$d template updated.'=>'"%1$s" dibuat. %2$d template diperbarui.' . "\0" . '','"%s" created.'=>'"%s" dibuat.','%d language not yet linked'=>'%d bahasa belum terhubung' . "\0" . '','%d link updated.'=>'%d tautan diperbarui.' . "\0" . '','%d locale pack installed.'=>'%d paket lokal terpasang.' . "\0" . '','%d navigation reference updated.'=>'%d referensi navigasi diperbarui.' . "\0" . '','%d part reference updated.'=>'%d referensi bagian diperbarui.' . "\0" . '','%s Archive'=>' Arsip %s','(avg %.1f hits/block)'=>'(rata-rata %.1f keberhasilan/blok)','(avg %.1f hits/entry)'=>'(rata-rata %.1f hits/entri)','(disabled)'=>'(dinonaktifkan)','({skipped} had no replaceable links — re-scan to investigate)'=>'({skipped} tidak memiliki tautan yang dapat diganti — lakukan pemindaian ulang untuk menyelidiki)','.txt file(s) in the directory'=>'.txt file(s) di direktori','<strong>Lingua Forge:</strong> %1$d localized template(s) from the &#8220;%2$s&#8221; theme are preserved in the database but are currently inactive. They will become active again if you reactivate that theme. To carry your translations to the new theme, regenerate them via <strong>Settings → Lingua Forge → Router → FSE scaffold</strong>.'=>'<strong>Lingua Forge:</strong> %1$d template yang dilokalisasi dari tema &#8220;%2$s&#8221; disimpan di database tetapi saat ini tidak aktif. Mereka akan aktif kembali jika Anda mengaktifkan kembali tema tersebut. Untuk membawa terjemahan Anda ke tema baru, regenerasi melalui <strong>Pengaturan → Lingua Forge → Router → FSE scaffold</strong>.','<strong>{n}</strong> auto-fixable link(s)'=>'<strong>{n}</strong> tautan yang dapat diperbaiki otomatis','<strong>{n}</strong> link(s) needing manual review'=>'<strong>{n}</strong> tautan yang membutuhkan tinjauan manual','<strong>{n}</strong> stale path(s)'=>'<strong>{n}</strong> jalur usang','<strong>{n}</strong> template issue(s)'=>'<strong>{n}</strong> masalah template','Accepts compiled .mo files only. Filename must follow the pattern {textdomain}-{locale}.mo. Uploading a file with the same name as an existing one will replace it.'=>'Hanya menerima file .mo yang dikompilasi. Nama file harus mengikuti pola {textdomain}-{locale}.mo. Mengunggah file dengan nama yang sama dengan yang sudah ada akan menggantinya.','Action'=>'Tindakan','Actions'=>'Tindakan','active'=>'aktif','Active Languages'=>'Bahasa Aktif','Active languages: add each language you want to support. Each language gets a URL prefix or subdomain and an hreflang tag in the page &lt;head&gt;.'=>'Bahasa aktif: tambahkan setiap bahasa yang ingin Anda dukung. Setiap bahasa mendapatkan awalan URL atau subdomain dan tag hreflang di bagian &lt;head&gt; halaman.','Active Provider'=>'Penyedia Aktif','Add entry'=>'Tambah entri','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register, include an FAQ block…'=>'Tambahkan instruksi untuk meningkatkan draf — misalnya buat lebih singkat, tambahkan bagian kesimpulan, gunakan register yang lebih formal, sertakan blok FAQ…','Add instructions to improve the draft — e.g. make it shorter, add a conclusion section, use a more formal register…'=>'Tambahkan instruksi untuk meningkatkan draf — misalnya buat lebih singkat, tambahkan bagian kesimpulan, gunakan register yang lebih formal…','Add new entry'=>'Tambah entri baru','Add one term per row. Both the source term and the target rendering are required. The language pair determines which translation jobs the constraint applies to.'=>'Tambahkan satu istilah per baris. Baik istilah sumber maupun tampilan target diperlukan. Pasangan bahasa menentukan pekerjaan terjemahan mana yang berlaku untuk batasan ini.','Adds a link to the home page so visitors can browse in their language.'=>'Menambahkan tautan ke halaman beranda agar pengunjung dapat menjelajah dalam bahasa mereka.','Administrators only (manage_options)'=>'Hanya administrator (manage_options)','After changing the primary language, flush permalinks (section below) for the URL routing to update.'=>'Setelah mengubah bahasa utama, bersihkan permalink (bagian di bawah) agar pengaturan URL diperbarui.','After changing URL structure settings (path prefix ↔ subdomain), always visit Settings → Permalinks and click Save Changes to flush the rewrite rules.'=>'Setelah mengubah pengaturan struktur URL (awalan jalur ↔ subdomain), selalu kunjungi Pengaturan → Tautan Permanen dan klik Simpan Perubahan untuk membersihkan aturan penulisan ulang.','AI Behaviour Preset'=>'Preset Perilaku AI','AI cache cleared. %d entry was removed.'=>'Cache AI dibersihkan. %d entri dihapus.' . "\0" . '','AI Cache: lists cached AI responses with hit counts. Clear the whole cache or a single post\'s entries. Use "Clear" before testing a translation change — cached results are returned even when you change the AI preset or model until the cache entry is evicted.'=>'Cache AI: daftar respons AI yang di-cache dengan jumlah hit. Bersihkan seluruh cache atau entri posting tunggal. Gunakan "Bersihkan" sebelum menguji perubahan terjemahan — hasil yang di-cache akan dikembalikan bahkan saat Anda mengubah preset AI atau model sampai entri cache dikeluarkan.','AI features are optional. Language routing, hreflang, the language switcher, and the translation group system all work without a provider configured.'=>'Fitur AI bersifat opsional. Pengaturan routing bahasa, hreflang, switcher bahasa, dan sistem grup terjemahan semuanya berfungsi tanpa penyedia yang dikonfigurasi.','AI Limits & Security'=>'Batas & Keamanan AI','AI provider returned an empty response.'=>' Penyedia AI mengembalikan respons kosong.','AI Usage'=>'Penggunaan AI','Aim for 120–160 characters. Leave empty to use the excerpt fallback.'=>'Targetkan 120–160 karakter. Biarkan kosong untuk menggunakan fallback kutipan.','All time'=>'Semua waktu','Allow editors to lock individual blocks'=>'Izinkan editor mengunci blok individual','Allow Gutenberg template-editing mode on post screens'=>'Izinkan mode pengeditan template Gutenberg di layar posting','Also delete language assignments, translation relationships, meta descriptions, glossary, and Translation Memory when the plugin is uninstalled'=>'Juga hapus penugasan bahasa, hubungan terjemahan, meta deskripsi, glosarium, dan Memori Terjemahan saat plugin dihapus','Also generate meta description'=>'Juga buat deskripsi meta','Alternative (server-side):'=>'Alternatif (sisi server):','An unknown error occurred.'=>'Terjadi kesalahan yang tidak diketahui.','and'=>'dan','Anthropic (Claude)'=>'Anthropic (Claude)','any'=>'apa saja','API calls saved by cache'=>'Panggilan API yang disimpan oleh cache','API Key'=>'Kunci API','API Keys'=>'Kunci API','API Keys Tab'=>'Tab Kunci API','API Response Cache'=>'Cache Respons API','Applied ✓'=>'Tersimpan ✓','Apply failed — please try again.'=>'Gagal menerapkan — silakan coba lagi.','Apply to Block'=>'Terapkan ke Blok','Apply to Editor'=>'Terapkan ke Editor','Apply to Footnote'=>'Terapkan ke Catatan Kaki','Apply to Meta Description'=>'Terapkan ke Deskripsi Meta','Apply translation'=>'Terapkan terjemahan','Applying…'=>'Sedang menerapkan…','Approximate size'=>'Ukuran perkiraan','Archive'=>' Arsip','Archive: %s'=>' Arsip: %s','Authors and above (edit_published_posts)'=>'Penulis dan di atasnya (edit_published_posts)','Behavior'=>'Perilaku','Behavior: choose the AI preset (Literal, Balanced, Creative), add site-wide custom prompt instructions, enable or disable automatic post-save translation, and configure the Translation Memory.'=>'Perilaku: pilih preset AI (Literal, Balanced, Creative), tambahkan instruksi prompt khusus situs, aktifkan atau nonaktifkan terjemahan otomatis setelah menyimpan posting, dan konfigurasikan Memori Terjemahan.','Block Content'=>'Konten Blok','block descriptionRenders a polite notice when the current page is being shown in its source language because no translation exists for the visitor\'s language. Driven by the Lingua Forge router\'s LINGUAFORGE_LANG_FALLBACK_ACTIVE signal — emits nothing when a translation exists for the request locale.'=>'Menampilkan pemberitahuan sopan saat halaman saat ini ditampilkan dalam bahasa sumbernya karena tidak ada terjemahan untuk bahasa pengunjung. Dikendalikan oleh sinyal LINGUAFORGE_LANG_FALLBACK_ACTIVE dari router Lingua Forge — tidak mengeluarkan apa pun saat terjemahan ada untuk lokal permintaan.','Block Editor'=>'Editor Blok','block keywordfallback'=>'fallback','block keywordi18n'=>'i18n','block keywordlanguage'=>'bahasa','block keywordlinguaforge'=>'linguaforge','block keywordtranslation'=>'terjemahan','Block locking'=>'Mengunci blok','Block patterns registered for custom post types. Use the Translate button to produce a language variant. The translated content is saved here and can be copied into any CPT post from the block editor Pattern inserter or used as a starting point for a Synced Pattern (Reusable Block).'=>'Polanya terdaftar untuk tipe pos khusus. Gunakan tombol Terjemahkan untuk menghasilkan varian bahasa. Konten yang diterjemahkan disimpan di sini dan dapat disalin ke pos CPT apa pun dari penyisip pola editor blok atau digunakan sebagai titik awal untuk Pola Sinkron (Blok yang Dapat Digunakan Kembali).','block titleMissing Translation Notice'=>'Pemberitahuan Terjemahan Hilang','Block translation reuses'=>'Penggunaan ulang terjemahan blok','Block-level translation cache shared across posts. When enabled, identical blocks (same markup, language pair, and glossary) are served from memory instead of calling the AI again. Configure in Settings → Behavior.'=>'Cache terjemahan tingkat blok yang dibagikan antar posting. Ketika diaktifkan, blok identik (markup yang sama, pasangan bahasa, dan glosarium) disajikan dari memori alih-alih memanggil AI lagi. Konfigurasi di Pengaturan → Perilaku.','Browser language redirect'=>'Pengalihan bahasa browser','Built-in preset instructions:'=>'Instruksi preset bawaan:','Bulletize (•-prefixed)'=>'Buat poin-poin (diawali •)','Cache translated equivalents at the block level so reusable content (shared footers, sidebars, accordions, boilerplate-heavy legal sections) does not pay an API call every time. When enabled, the translation flow parses each post into blocks, looks each block up in the cache, and sends only uncached blocks to the AI in a single batched request. Glossary edits and Compliance preset changes automatically invalidate affected cached translations. View statistics and clear the cache under Maintenance.'=>'Cache padanan terjemahan di tingkat blok agar konten yang dapat digunakan kembali (footer bersama, sidebar, akordeon, bagian hukum yang banyak boilerplate) tidak memanggil API setiap kali. Saat diaktifkan, alur terjemahan mem-parsing setiap posting ke dalam blok, mencari setiap blok di cache, dan hanya mengirim blok yang tidak di-cache ke AI dalam satu permintaan batch. Suntingan glosarium dan perubahan preset Kepatuhan secara otomatis membatalkan cache terjemahan yang terpengaruh. Lihat statistik dan bersihkan cache di bawah Pemeliharaan.','cached'=>'disimpan sementara','Cached API responses'=>'Respons API yang di-cache','Cached block translations'=>'Terjemahan blok yang di-cache','Cancel'=>'Batal','Cannot determine target language from slug.'=>' Tidak dapat menentukan bahasa target dari slug.','Cap how much AI usage the site can generate and restrict which user roles may trigger paid AI calls. Sits on top of the per-user rate limit (30 requests / minute, hardcoded) that already protects against single-user runaway loops.'=>'Batasi penggunaan AI yang dapat dihasilkan situs dan batasi peran pengguna yang dapat memicu panggilan AI berbayar. Terletak di atas batas laju per pengguna (30 permintaan / menit, dikodekan keras) yang sudah melindungi terhadap loop liar pengguna tunggal.','chars'=>'karakter','Chunk translated'=>'Potongan yang diterjemahkan','Chunk translated to:'=>'Potongan yang diterjemahkan ke:','Clear'=>'Hapus','Clear All'=>'Hapus Semua','Clear all cached AI results? Future requests will trigger fresh API calls until the cache rebuilds.'=>'Bersihkan semua hasil AI yang di-cache? Permintaan di masa depan akan memicu panggilan API baru sampai cache dibangun kembali.','Clear API Response Cache'=>'Hapus Cache Respons API','Clear Debug Files'=>'Hapus File Debug','Clear hints'=>'Hapus petunjuk','Clear input'=>'Hapus input','Clear the entire Translation Memory? Future translations will rebuild the cache as they run.'=>'Hapus seluruh Memori Terjemahan? Terjemahan di masa depan akan membangun kembali cache saat mereka berjalan.','Clear Translation Memory'=>'Hapus Memori Terjemahan','Close'=>'Tutup','Close language panel'=>'Tutup panel bahasa','Close popover'=>'Tutup popover','Compliance Preset'=>'Preset Kepatuhan','Content generated'=>'Konten yang dibuat','Content Generator'=>'Generator Konten','Content ready'=>'Konten siap','Contributors and above — default (edit_posts)'=>'Kontributor dan di atasnya — default (edit_posts)','Control how much content is sent to the AI and how large the response can be. Leave a field blank to use the built-in default (shown as placeholder). Raise these values if large pages are being cut off; lower them to reduce API costs.'=>'Kontrol berapa banyak konten yang dikirim ke AI dan seberapa besar respons yang dapat diberikan. Tinggalkan bidang kosong untuk menggunakan default bawaan (ditampilkan sebagai placeholder). Tingkatkan nilai ini jika halaman besar terpotong; turunkan untuk mengurangi biaya API.','Controls the token budget and input limits for the AI Content Generator feature. Leave fields blank to use the built-in defaults.'=>'Mengontrol anggaran token dan batas input untuk fitur Generator Konten AI. Biarkan bidang kosong untuk menggunakan default bawaan.','Controls what happens when an administrator deletes the plugin from Plugins → Installed Plugins → Delete. Plugin settings and AI caches are always removed. Language assignments and translation relationships are kept by default so an accidental uninstall or a reinstall can pick up where it left off.'=>'Mengontrol apa yang terjadi ketika administrator menghapus plugin dari Plugins → Installed Plugins → Delete. Pengaturan plugin dan cache AI selalu dihapus. Penugasan bahasa dan hubungan terjemahan secara default dipertahankan sehingga penghapusan tidak sengaja atau pemasangan ulang dapat melanjutkan dari tempat terakhir.','Conversational'=>' Percakapan','Copied ✓'=>'Disalin ✓','Copy'=>'Salin','Copy markup'=>'Salin markup','Copy the result and paste it wherever needed (e.g. directly into the footnote field).'=>'Salin hasilnya dan tempelkan di mana pun diperlukan (misalnya langsung ke bidang catatan kaki).','Copy to safe storage'=>'Salin ke penyimpanan aman','Could not add entry: source term and target term are required.'=>'Tidak dapat menambahkan entri: istilah sumber dan istilah target diperlukan.','Could not copy the file. Check that the uploads folder is writable.'=>'Tidak dapat menyalin file. Periksa apakah folder unggahan dapat ditulis.','Could not instantiate the provider.'=>'Tidak dapat menginisialisasi penyedia.','Could not save the file. Check that the uploads folder is writable.'=>'Tidak dapat menyimpan file. Periksa apakah folder unggahan dapat ditulis.','Could not save the glossary entry.'=>'Tidak dapat menyimpan entri glosarium.','CPT Block Patterns'=>'Polanya Blok CPT','Create'=>'Buat','Create missing'=>'Buat yang hilang','Creating translations for post type "%s" requires an active integration. Please ensure the required integration is installed and active.'=>'Membuat terjemahan untuk tipe pos "%s" memerlukan integrasi aktif. Pastikan integrasi yang diperlukan terpasang dan aktif.','Creating…'=>'Sedang membuat…','Creative / Marketing'=>'Kreatif / Pemasaran','Creative / Marketing instructions'=>'Instruksi Kreatif / Pemasaran','Current content (will be overwritten)'=>'Isi saat ini (akan ditimpa)','Current title'=>'Judul saat ini','Current: {current}'=>'Saat ini: {current}','Currently inherited from the %s constant. Selecting a value here will override it.'=>'Saat ini diwarisi dari konstanta %s. Memilih nilai di sini akan mengesampinginya.','Currently skipped for posts that use block-comment attribute placeholders (wp:details summary fields, etc.) — they fall through to the existing single-call translation path.'=>'Saat ini dilewati untuk posting yang menggunakan placeholder atribut komentar blok (wp:details bidang ringkasan, dll.) — mereka akan melewati jalur terjemahan panggilan tunggal yang ada.','Currently:'=>'Saat ini:','Custom'=>'Kustom','Daily AI quota reached (%1$d requests). Resets at %2$s UTC.'=>'Kuota AI harian tercapai (%1$d permintaan). Reset pada %2$s UTC.','Daily request limit'=>'Batas permintaan harian','Debug Files'=>'File Debug','Debug files cleared. %d file was removed.'=>'File debug dibersihkan. %d file dihapus.' . "\0" . '','Debug logging'=>'Pencatatan debug','Debug logging disabled.'=>'Pencatatan debug dinonaktifkan.','Debug logging enabled.'=>'Pencatatan debug diaktifkan.','Debug: enable the debug log to capture AI prompts and API responses to a local file. Disable after troubleshooting — debug mode writes a file on every AI request.'=>'Debug: aktifkan log debug untuk menangkap prompt AI dan respons API ke file lokal. Nonaktifkan setelah pemecahan masalah — mode debug menulis file pada setiap permintaan AI.','Delete'=>'Hapus','Delete all .txt files in the debug directory? The directory itself will remain so future debug writes still land cleanly.'=>'Hapus semua file .txt di direktori debug? Direktori itu sendiri akan tetap ada sehingga penulisan debug di masa depan tetap bersih.','Delete all files for this override (both .mo and .po)?'=>'Hapus semua file untuk penimpa ini (baik .mo maupun .po)?','Delete content data on uninstall'=>'Hapus data konten saat uninstall','Delete this glossary entry?'=>'Hapus entri glosarium ini?','Describe what to write — topic, key points, structure…'=>'Jelaskan apa yang harus ditulis — topik, poin utama, struktur…','Directory'=>'Direktori','Disable during prompt tuning or when you need every request to reach the AI provider. Disabling does not delete cached entries — re-enabling restores them. Increasing API spend immediately on busy sites is expected when disabled.'=>'Nonaktifkan selama penyesuaian prompt atau saat Anda membutuhkan setiap permintaan mencapai penyedia AI. Menonaktifkan tidak menghapus entri yang di-cache — mengaktifkannya kembali memulihkannya. Meningkatkan pengeluaran API secara langsung di situs yang sibuk diharapkan saat dinonaktifkan.','Display'=>'Tampilan','Displays the Lingua Forge language switcher.'=>'Menampilkan pengalih bahasa Lingua Forge.','Documentation'=>'Dokumentasi','Done'=>'Selesai','Done — {done} of {total} post(s) fixed.'=>'Selesai — {done} dari {total} posting diperbaiki.','Down'=>'Bawah','Download and install a WordPress core language pack directly from WordPress.org. Once installed, the locale becomes available for URL routing and the AI translation workflow. The list of available languages is fetched on demand — click the button below to load it.'=>'Unduh dan pasang paket bahasa inti WordPress langsung dari WordPress.org. Setelah terpasang, locale menjadi tersedia untuk routing URL dan alur kerja terjemahan AI. Daftar bahasa yang tersedia diambil sesuai permintaan — klik tombol di bawah untuk memuatnya.','Dropdown direction'=>'Arah dropdown','Editors and above (edit_others_posts)'=>'Editor dan di atasnya (edit_others_posts)','Enable API response caching'=>'Aktifkan caching respons API','Enable block-level translation cache reuse across posts'=>'Aktifkan penggunaan kembali cache terjemahan tingkat blok di seluruh posting','Enter your API key for at least one AI provider. Keys are encrypted at rest using AES-256-GCM with a site-specific secret (LINGUAFORGE_SECRET). Do not share database exports without rotating the secret first.'=>'Masukkan kunci API Anda untuk setidaknya satu penyedia AI. Kunci dienkripsi saat istirahat menggunakan AES-256-GCM dengan rahasia khusus situs (LINGUAFORGE_SECRET). Jangan bagikan ekspor basis data tanpa mengganti rahasia terlebih dahulu.','environment variable'=>'variabel lingkungan','Error'=>'Kesalahan','Expand'=>'Perluas','Expected: {expected}'=>'Diharapkan: {expected}','Extra guidance — tone, style, constraints, target audience…'=>'Panduan tambahan — nada, gaya, batasan, audiens target…','Extra guidance — tone, style, constraints…'=>'Panduan tambahan — nada, gaya, batasan…','Failed. Please try again.'=>'Gagal. Silakan coba lagi.','Feature'=>'Fitur','Features are grouped into two tiers. Enter the exact model identifier for each tier and provider. Leave a field blank to use the built-in default (shown as placeholder). Only the active provider\'s models are called at runtime — configure the others in advance if you plan to switch.'=>'Fitur dikelompokkan menjadi dua tingkat. Masukkan pengenal model yang tepat untuk setiap tingkat dan penyedia. Tinggalkan bidang kosong untuk menggunakan default bawaan (ditampilkan sebagai placeholder). Hanya model dari penyedia aktif yang dipanggil saat runtime — konfigurasikan yang lain sebelumnya jika Anda berencana beralih.','File copied to safe storage successfully.'=>'File berhasil disalin ke penyimpanan aman.','Files'=>'File','Files land in the directory below. Useful for diagnosing translation issues — turn off once you have what you need so the files do not accumulate. You can also force this from wp-config.php with `define( \'LINGUAFORGE_AI_DEBUG\', true );` which overrides the toggle.'=>'File disimpan di direktori di bawah ini. Berguna untuk mendiagnosis masalah terjemahan — matikan setelah Anda mendapatkan apa yang Anda butuhkan agar file tidak menumpuk. Anda juga dapat memaksa ini dari wp-config.php dengan `define( \'LINGUAFORGE_AI_DEBUG\', true );` yang akan menimpa toggle.','Filter'=>'Filter','Filter with linguaforge_debug_dir to redirect debug output to a non-public location.'=>'Filter dengan linguaforge_debug_dir untuk mengarahkan output debug ke lokasi yang tidak publik.','Fix'=>'Perbaiki','Fix All'=>'Perbaiki Semua','Fix all links'=>'Perbaiki semua tautan','Fix all parts'=>'Perbaiki semua bagian','Fix Links'=>'Perbaiki Tautan','Fix Nav'=>'Perbaiki Navigasi','Fix Parts'=>'Perbaiki Bagian','Fix Template'=>'Perbaiki Template','Fixing {n} / {total}…'=>'Memperbaiki {n} / {total}…','Fixing…'=>'Memperbaiki…','Flush Permalink Rules'=>'Flush Permalink Rules','Flush Permalinks'=>'Flush Permalinks','Footnote Content'=>'Isi Catatan Kaki','footnote(s) translated — applied together with content.'=>'Catatan kaki yang diterjemahkan — diterapkan bersama konten.','Footnotes'=>'Catatan kaki','Footnotes payload (advanced)'=>'Payload catatan kaki (lanjutan)','Forbidden'=>'Dilarang','Forced OFF by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Dipaksa OFF oleh konstanta LINGUAFORGE_AI_DEBUG di wp-config.php. Hapus baris itu untuk mengontrol toggle ini dari sini.','Forced ON by the LINGUAFORGE_AI_DEBUG constant in wp-config.php. Remove that line to control this toggle from here.'=>'Dipaksa ON oleh konstanta LINGUAFORGE_AI_DEBUG di wp-config.php. Hapus baris itu untuk mengontrol toggle ini dari sini.','Found {parts} across <strong>{total}</strong> of <strong>{scanned}</strong> scanned post(s) for <strong>{lang}</strong>.'=>'Ditemukan {parts} di seluruh <strong>{total}</strong> dari <strong>{scanned}</strong> posting yang dipindai untuk <strong>{lang}</strong>.','From'=>'Dari','Front Page'=>' Halaman Depan','FSE localisation: scaffold, translate, and fix links in Full Site Editing templates and template parts directly from this tab.'=>'lokalisasi FSE: buat, terjemahkan, dan perbaiki tautan dalam template dan bagian template Pengeditan Situs Penuh langsung dari tab ini.','FSE templates seeded from the active theme. Create then customise in the Site Editor.'=>'Template FSE disemai dari tema aktif. Buat lalu sesuaikan di Editor Situs.','Full Article'=>'Artikel Penuh','Full post'=>'Pos lengkap','General'=>'Umum','Generate'=>'Hasilkan','Generate Content'=>'Hasilkan Konten','Generate content…'=>'Hasilkan konten…','Generate Excerpt'=>'Hasilkan Kutipan','Generate Meta Description'=>'Hasilkan Deskripsi Meta','Generated Content'=>'Konten yang dihasilkan','Generated meta description'=>'Meta deskripsi yang dihasilkan','Generating…'=>'Sedang menghasilkan…','Generation failed.'=>'Gagal menghasilkan.','Getting started'=>'Memulai','Global AI preset'=>'Preset AI global','Global default (%s)'=>'Default global (%s)','Glossary'=>'Glosarium','Glossary entry added.'=>'Entri glosarium ditambahkan.','Glossary entry removed.'=>'Entri glosarium dihapus.','Glossary Tab'=>'Tab Glosarium','Google (Gemini)'=>'Google (Gemini)','Hide'=>'Sembunyikan','Hints'=>'Petunjuk','Home link text'=>'Teks tautan beranda','How it should appear in the translation. Type the same value as the source term to instruct the AI to preserve it verbatim.'=>'Bagaimana seharusnya muncul dalam terjemahan. Ketik nilai yang sama dengan istilah sumber untuk menginstruksikan AI agar mempertahankannya secara verbatim.','https://github.com/leotiger/lingua-forge'=>'https://github.com/leotiger/lingua-forge','https://lingua-forge.com'=>'https://lingua-forge.com','Icon + label'=>'Ikon + label','Icon only'=>'Hanya ikon','If checked, uninstalling the plugin will permanently delete all language assignments, translation relationships, meta descriptions, per-page presets, the AI glossary, and Translation Memory for every post on this site. This cannot be undone. Leave unchecked unless you are fully removing multilingual support from the site.'=>'Jika dicentang, menghapus plugin akan secara permanen menghapus semua penugasan bahasa, hubungan terjemahan, meta deskripsi, preset per halaman, glosarium AI, dan Memori Terjemahan untuk setiap posting di situs ini. Ini tidak dapat dibatalkan. Biarkan tidak dicentang kecuali Anda benar-benar menghapus dukungan multibahasa dari situs.','Improve writing'=>'Perbaiki penulisan','Informative'=>' Informatif','Input tokens'=>'Token input','Install'=>'Pasang','Install a Language'=>'Pasang Bahasa','Installing…'=>'Menginstal…','Instructions (optional)'=>'Instruksi (opsional)','Instructions / key points'=>'Instruksi / poin utama','Integration API'=>'API Integrasi','Internal Link Fixer'=>'Perbaikan Tautan Internal','Introduction only'=>'Hanya pengantar','Invalid file reference.'=>'Referensi file tidak valid.','Invalid filename.'=>'Nama file tidak valid.','Invalid language.'=>'Bahasa tidak valid.','Invalid locale code.'=>'Kode locale tidak valid.','Invalid or primary language.'=>' Bahasa tidak valid atau utama.','Invalid post type.'=>' Jenis posting tidak valid.','Invalid template part.'=>' Bagian template tidak valid.','Invalid template type.'=>' Jenis template tidak valid.','Key points, ideas, or structure to build from…'=>'Poin utama, ide, atau struktur untuk dibangun…','Keys are encrypted with AES-256-CBC before being stored in the WordPress database. The encryption secret is derived from your WordPress auth salts (wp-config.php), so plaintext keys never touch the database.'=>'Kunci API dienkripsi dengan AES-256-CBC sebelum disimpan di basis data WordPress. Rahasia enkripsi diambil dari garam otentikasi WordPress Anda (wp-config.php), sehingga kunci teks biasa tidak pernah menyentuh basis data.','Language'=>'Bahasa','Language %s installed successfully.'=>'Bahasa %s berhasil dipasang.','Language (optional)'=>'Bahasa (opsional)','Language installation is disabled on this server (DISALLOW_FILE_MODS is set).'=>'Pemasangan bahasa dinonaktifkan di server ini (DISALLOW_FILE_MODS diatur).','Language installation is disabled on this server. The DISALLOW_FILE_MODS constant is set in wp-config.php. Install language packs manually via WP-CLI: wp language core install de_DE'=>'Pemasangan bahasa dinonaktifkan di server ini. Konstanta DISALLOW_FILE_MODS diatur di wp-config.php. Pasang paket bahasa secara manual melalui WP-CLI: wp language core install de_DE','Language label'=>'Label bahasa','Language Overrides'=>'Penyesuaian Bahasa','Language Overrides: manage custom .po/.mo override files for the Lingua Forge UI strings. Use this instead of editing plugin files directly — overrides survive updates.'=>'Overriding bahasa: kelola file override .po/.mo khusus untuk string UI Lingua Forge. Gunakan ini daripada mengedit file plugin secara langsung — override tetap ada setelah pembaruan.','Language pack installation failed. The language may already be installed, the locale code may be incorrect, or your server may block file writes.'=>'Gagal memasang paket bahasa. Bahasa mungkin sudah terpasang, kode locale mungkin salah, atau server Anda memblokir penulisan file.','Language Setup'=>'Pengaturan Bahasa','Language Switcher'=>'Pengalih Bahasa','Language switcher'=>'Switcher bahasa','Language-specific copies of the theme\'s template parts. Once scaffolded, templates are updated to reference the language-specific part.'=>'Salinan khusus bahasa dari bagian template tema. Setelah dibuat, template diperbarui untuk merujuk ke bagian khusus bahasa.','Language:'=>'Bahasa:','Languages currently known to the router (derived from installed WordPress locale packs plus the primary language). Install additional language packs in the section below to make more languages available for routing and translation.'=>'Bahasa yang saat ini dikenal oleh router (berasal dari paket lokal WordPress yang terpasang plus bahasa utama). Pasang paket bahasa tambahan di bagian di bawah ini agar lebih banyak bahasa tersedia untuk routing dan terjemahan.','Last 30 days'=>'30 hari terakhir','Last 7 days'=>'7 hari terakhir','Lead paragraph (≤60 w)'=>'Paragraf pembuka (≤60 kata)','Leave a model field blank to use the built-in default for that tier. The placeholder text shows which model will be used.'=>'Biarkan bidang model kosong untuk menggunakan default bawaan untuk tingkat tersebut. Teks placeholder menunjukkan model mana yang akan digunakan.','Leave blank for brand names and language-agnostic terms that should be enforced regardless of which language we are translating from.'=>'Biarkan kosong untuk nama merek dan istilah yang tidak bergantung bahasa yang harus ditegakkan terlepas dari bahasa apa yang kita terjemahkan.','Leave blank to apply this entry to all target languages — ideal for brand names, abbreviations, and terms that must be preserved verbatim in every translation.'=>'Biarkan kosong untuk menerapkan entri ini ke semua bahasa target — ideal untuk nama merek, singkatan, dan istilah yang harus dipertahankan secara verbatim dalam setiap terjemahan.','Leave blank to keep the existing key. Enter a new value to replace it.'=>'Biarkan kosong untuk mempertahankan kunci yang ada. Masukkan nilai baru untuk menggantinya.','Leave blank to use the built-in default. Clearing a saved override restores the default on next save.'=>'Biarkan kosong untuk menggunakan default bawaan. Menghapus override yang disimpan akan mengembalikan ke default saat penyimpanan berikutnya.','Legal / Compliance'=>'Hukum / Kepatuhan','Legal / Compliance instructions'=>'Instruksi Hukum / Kepatuhan','Light'=>'Ringan','Light (default — fast and cost-effective)'=>'Ringan (default — cepat dan hemat biaya)','Light (fast and cost-effective — Haiku / Flash)'=>'Ringan (cepat dan hemat biaya — Haiku / Flash)','Light: used for meta descriptions and excerpt generation — fast, low cost.'=>'Ringan: digunakan untuk deskripsi meta dan pembuatan kutipan — cepat, biaya rendah.','Limit results to pages in the given Lingua Forge language code.'=>'Batasi hasil ke halaman dalam kode bahasa Lingua Forge yang diberikan.','Limits'=>'Batasan','Lingua Forge'=>'Lingua Forge','Lingua Forge adds multilingual routing, AI-powered translation, hreflang SEO tags, and a language switcher to your WordPress site.'=>'Lingua Forge menambahkan routing multibahasa, terjemahan berbasis AI, tag SEO hreflang, dan switcher bahasa ke situs WordPress Anda.','Lingua Forge AI Tools'=>'Alat AI Lingua Forge','Lingua Forge restricts two Gutenberg features by default to keep editorial behavior consistent across languages. Opt in here when you need full Gutenberg / FSE capabilities.'=>'Lingua Forge membatasi dua fitur Gutenberg secara default untuk menjaga konsistensi perilaku editorial di berbagai bahasa. Pilih di sini jika Anda membutuhkan kemampuan Gutenberg / FSE penuh.','Lingua Forge Settings'=>'Pengaturan Lingua Forge','Lingua Forge uses two independent caching layers to avoid redundant AI API calls. Use the tabs below to inspect and manage each one.'=>'Lingua Forge menggunakan dua lapisan cache independen untuk menghindari panggilan API AI yang berulang. Gunakan tab di bawah untuk memeriksa dan mengelola masing-masing.','Lingua Forge uses two model tiers per provider:'=>'Lingua Forge menggunakan dua tingkat model per penyedia:','Lingua Forge — Quick Translate'=>'Lingua Forge — Terjemahan Cepat','Lingua Forge — Settings'=>'Lingua Forge — Pengaturan','link(s)'=>'tautan','Links'=>'Tautan','Load available languages'=>'Muat bahasa yang tersedia','Loading…'=>'Memuat…','Loco Translate stores its custom translations in wp-content/languages/loco/ — a location that can be silently wiped by a WP core update, plugin reinstall, or if Loco Translate itself is removed. Copying files here moves them into the Lingua Forge i18n-overrides directory, which persists through all of those events and is loaded automatically on every request.'=>'Loco Translate menyimpan terjemahan khususnya di wp-content/languages/loco/ — lokasi yang dapat dihapus secara diam-diam oleh pembaruan inti WP, pemasangan ulang plugin, atau jika Loco Translate sendiri dihapus. Menyalin file di sini memindahkan mereka ke direktori Lingua Forge i18n-overrides, yang tetap ada melalui semua kejadian tersebut dan dimuat secara otomatis setiap permintaan.','Loco Translate — Copy to Safe Storage'=>'Loco Translate — Salin ke Penyimpanan Aman','Lowest WordPress capability allowed to trigger AI features. Tightening this on multi-author sites prevents Contributors or trial accounts from running paid AI calls. Override per-feature via the linguaforge_required_capability filter.'=>'Kemampuan WordPress terendah yang diizinkan untuk memicu fitur AI. Memperketat ini di situs multi-penulis mencegah Kontributor atau akun percobaan menjalankan panggilan AI berbayar. Override per fitur melalui filter linguaforge_required_capability.','Maintenance'=>'Pemeliharaan','Maintenance Tab'=>'Tab Pemeliharaan','Make casual'=>'Buat santai','Make concise'=>'Buat ringkas','Make formal'=>'Buat formal','Mark citations needed'=>'Tandai kutipan yang diperlukan','Max context characters'=>'Jumlah karakter konteks maksimum','Max hints characters'=>'Jumlah karakter petunjuk maksimum','Max input characters'=>'Karakter input maksimum','Max output tokens'=>'Token output maksimum','Maximum characters accepted from the input field. Default: 8 000.'=>'Jumlah karakter maksimum yang diterima dari bidang input. Default: 8.000.','Maximum characters of existing post content passed to the AI as seed context when no Hints are provided. Default: 6 000.'=>'Jumlah karakter konten posting yang ada yang diteruskan ke AI sebagai konteks benih saat tidak ada Petunjuk yang disediakan. Default: 6.000.','Maximum characters read from the Hints field. Default: 2 000.'=>'Jumlah karakter maksimum yang dibaca dari bidang Petunjuk. Default: 2.000.','Maximum number of characters of post content forwarded to the AI. 0 means no limit — the full content is always sent (recommended). Set a non-zero value only if your provider has a tight context window. A warning is written to the PHP error log whenever the content is trimmed.'=>'Jumlah karakter maksimum dari konten posting yang diteruskan ke AI. 0 berarti tidak ada batas — seluruh konten selalu dikirim (disarankan). Tetapkan nilai non-nol hanya jika penyedia Anda memiliki jendela konteks yang ketat. Peringatan akan ditulis ke log kesalahan PHP setiap kali konten dipangkas.','Maximum number of tokens the AI may produce in a single translation response. If a translation is silently cut off at the end, increase this value. Default: 16 000.'=>'Jumlah token maksimum yang dapat diproduksi AI dalam satu respons terjemahan. Jika terjemahan dipotong secara diam-diam di akhir, tingkatkan nilai ini. Default: 16.000.','Maximum tokens the AI may produce per generation run. Raise this if full articles are being cut off. Default: 8 192.'=>'Token maksimum yang dapat diproduksi AI per jalannya generasi. Tingkatkan ini jika artikel lengkap terpotong. Default: 8.192.','Maximum tokens the AI may produce per quick translation. Default: 2 000.'=>'Token maksimum yang dapat diproduksi AI per terjemahan cepat. Default: 2.000.','Meta Description'=>'Meta Deskripsi','Meta Description, Excerpt Generator'=>'Meta Deskripsi, Generator Kutipan','Minimum role'=>'Peran minimum','Missing pattern name or language.'=>' Nama pola atau bahasa yang hilang.','Mode'=>'Mode','Model'=>'Model','Model tier'=>'Tingkat model','Models'=>'Model','Models Tab (General)'=>'Tab Model (Umum)','Most recent cached block'=>'Blok cache terbaru','Most recent cached response'=>'Respons cache terbaru','Multilingual routing, SEO meta tags, and AI content tools for WordPress. Combines language detection, URL routing, hreflang, meta descriptions, and AI-powered excerpt, meta, and translation features.'=>'Routing multibahasa, meta tag SEO, dan alat konten AI untuk WordPress. Menggabungkan deteksi bahasa, routing URL, hreflang, deskripsi meta, dan fitur kutipan, meta, serta terjemahan yang didukung AI.','Name displayed in this language. Leave empty to use the source name.'=>'Nama yang ditampilkan dalam bahasa ini. Biarkan kosong untuk menggunakan nama sumber.','Navigation'=>'Navigasi','Navigation has no content to translate.'=>'Navigasi tidak memiliki konten untuk diterjemahkan.','Navigation not found.'=>'Navigasi tidak ditemukan.','Navigation posts are translated via the Router tab, not this button.'=>'Pos navigasi diterjemahkan melalui tab Router, bukan tombol ini.','Navigation translation requires an active AI provider. Configure an API key in the API Keys tab.'=>'Terjemahan navigasi memerlukan penyedia AI aktif. Konfigurasikan kunci API di tab Kunci API.','Navigations'=>'Navigasi','Network error — could not reach the WordPress AJAX endpoint.'=>'Kesalahan jaringan — tidak dapat menghubungi endpoint AJAX WordPress.','No %s version found in this translation group.'=>'Tidak ditemukan versi %s dalam grup terjemahan ini.','No AI provider configured.'=>' Penyedia AI tidak dikonfigurasi.','No AI usage recorded in the selected window (%s). Pick a wider range above.'=>'Penggunaan AI tidak tercatat dalam jendela yang dipilih (%s). Pilih rentang yang lebih luas di atas.','No AI usage recorded yet. Once an editor runs a translation, generates a meta description, or uses any other AI feature, totals will appear here.'=>'Penggunaan AI belum tercatat. Setelah editor menjalankan terjemahan, menghasilkan deskripsi meta, atau menggunakan fitur AI lainnya, total akan muncul di sini.','No API key configured for this provider.'=>'Tidak ada kunci API yang dikonfigurasi untuk penyedia ini.','No built-in instructions — each AI feature uses its own tuned defaults. Fill in the Custom prompt instructions field below to add your own site-wide rules.'=>'Tidak ada instruksi bawaan — setiap fitur AI menggunakan default yang disesuaikan sendiri. Isi bidang instruksi Kustom di bawah ini untuk menambahkan aturan situs Anda sendiri.','No custom Loco Translate files found yet. They appear here once you save a translation in Loco Translate.'=>'Belum ada file Loco Translate khusus yang ditemukan. Mereka akan muncul di sini setelah Anda menyimpan terjemahan di Loco Translate.','No file was selected.'=>'Tidak ada file yang dipilih.','No glossary entries match the current filter. Clear the filter to see all entries, or add a new entry below.'=>'Tidak ada entri glosarium yang cocok dengan filter saat ini. Bersihkan filter untuk melihat semua entri, atau tambahkan entri baru di bawah.','No glossary entries yet. Add one below to start enforcing terminology in translations.'=>'Belum ada entri glosarium. Tambahkan di bawah untuk mulai menegakkan terminologi dalam terjemahan.','No internal links found to update.'=>' Tidak ditemukan tautan internal untuk diperbarui.','No language-specific template parts found to map.'=>' Tidak ditemukan bagian template khusus bahasa untuk dipetakan.','No navigation references needed updating.'=>' Tidak diperlukan pembaruan referensi navigasi.','No override files uploaded yet.'=>'Belum ada file penimpa yang diunggah.','No response from provider — check the error log for details.'=>'Tidak ada respons dari penyedia — periksa log error untuk detailnya.','No secondary languages configured. Install a language pack above to enable template scaffolding.'=>'Tidak ada bahasa sekunder yang dikonfigurasi. Pasang paket bahasa di atas untuk mengaktifkan kerangka template.','No source content found to translate.'=>'Tidak ada konten sumber yang ditemukan untuk diterjemahkan.','No source page linked yet.'=>'Belum ada halaman sumber yang terhubung.','No template part references needed updating.'=>' Tidak diperlukan pembaruan referensi bagian template.','No {lang} translation registered (TRID missing)'=>'Belum ada terjemahan {lang} yang terdaftar (TRID hilang)','Notes'=>'Catatan','Notice message'=>'Pesan pemberitahuan','Notice settings'=>'Pengaturan pemberitahuan','Oldest cached block'=>'Blok cache tertua','Oldest cached response'=>'Respons cache tertua','Only .mo files are accepted.'=>'Hanya file .mo yang diterima.','OpenAI (GPT)'=>'OpenAI (GPT)','Optional context for editors (e.g. "ASIC = Application-Specific Integrated Circuit; preserve in English in technical contexts").'=>'Konteks opsional untuk editor (misalnya "ASIC = Sirkuit Terintegrasi Khusus Aplikasi; pertahankan dalam bahasa Inggris dalam konteks teknis").','Output'=>'Output','Output tokens'=>'Token output','overridden'=>'yang diubah','Override file deleted.'=>'File penimpa dihapus.','Override file uploaded successfully.'=>'File penimpa berhasil diunggah.','Overrides the AI preset for Translation and Content Generation on this page. All other features always use the global preset.'=>'Mengganti preset AI untuk Terjemahan dan Pembuatan Konten di halaman ini. Semua fitur lainnya selalu menggunakan preset global.','Overrides the AI preset for Translation and Content Generation on this page. Site-wide custom prompt instructions (Settings → Behavior) are always appended to every request regardless of this selection.'=>'Mengganti preset AI untuk Terjemahan dan Pembuatan Konten di halaman ini. Instruksi prompt kustom di seluruh situs (Pengaturan → Perilaku) selalu ditambahkan ke setiap permintaan terlepas dari pilihan ini.','Overview'=>'Ikhtisar','Page'=>'Halaman','Part'=>'Bagian','Paste a footnote, sentence, or any snippet here…'=>'Tempelkan catatan kaki, kalimat, atau potongan apa pun di sini…','Paste text, or select text in the editor first…'=>'Tempel teks, atau pilih teks di editor terlebih dahulu…','Paste text, or select text on the page first…'=>'Tempel teks, atau pilih teks di halaman terlebih dahulu…','Paste your API key…'=>'Tempelkan kunci API Anda…','Path prefix — example.com/de/'=>'Prefix path — example.com/de/','Pattern'=>'Pola','Pattern has no content to translate.'=>' Pola tidak memiliki konten untuk diterjemahkan.','Pattern not found.'=>' Pola tidak ditemukan.','Pattern translated and saved. Copy the content into your CPT post via the block editor Pattern inserter or use it as a starting point for a Reusable Block.'=>' Pola diterjemahkan dan disimpan. Salin konten ke posting CPT Anda melalui inserter pola editor blok atau gunakan sebagai titik awal untuk Blok yang Dapat Digunakan Kembali.','Pattern translation failed.'=>'Gagal menerjemahkan pola.','Per-post cache for AI-generated translations, meta descriptions, excerpts, and content. Always active — no separate toggle required. Entries are invalidated automatically when the content or AI provider/model changes. Use the toolbar "↺ Re-translate" button or click Clear below to force a fresh API call.'=>'Cache per-post untuk terjemahan yang dihasilkan AI, deskripsi meta, kutipan, dan konten. Selalu aktif — tidak memerlukan saklar terpisah. Entri akan kedaluwarsa secara otomatis saat konten atau penyedia/model AI berubah. Gunakan tombol "↺ Terjemahkan Ulang" di toolbar atau klik Bersihkan di bawah untuk memaksa panggilan API baru.','Permalink rules flushed successfully.'=>'Aturan permalink berhasil dibersihkan.','Permission denied.'=>' Izin ditolak.','Persuasive'=>' Persuasif','PHP constant'=>'Konstanta PHP','Pin terms that must not be translated or must always be rendered in a specific way (e.g. brand names, product names, acronyms). Glossary constraints are injected into every AI translation request for all features: post translation, meta description, excerpt, and FSE template translation.'=>'Tandai istilah yang tidak boleh diterjemahkan atau harus selalu ditampilkan dengan cara tertentu (misalnya nama merek, nama produk, akronim). Batasan glosarium disuntikkan ke setiap permintaan terjemahan AI untuk semua fitur: terjemahan posting, deskripsi meta, kutipan, dan terjemahan template FSE.','Plain language'=>'Bahasa sederhana','Please enter some instructions first…'=>'Harap masukkan beberapa instruksi terlebih dahulu…','Please enter some text first…'=>'Harap masukkan beberapa teks terlebih dahulu…','Post'=>'Posting','Post not found.'=>'Posting tidak ditemukan.','Post Types'=>'Tipe Pos','Prefilled from excerpt. Edit to override.'=>'Diisi dari kutipan. Sunting untuk menimpa.','Primary Language'=>'Bahasa Utama','Primary language'=>'Bahasa utama','Primary language saved.'=>'Bahasa utama disimpan.','Primary language: the language your existing content is written in. All translations are produced from this language; changing it does not move or delete any posts.'=>'Bahasa utama: bahasa di mana konten Anda yang ada ditulis. Semua terjemahan diproduksi dari bahasa ini; mengubahnya tidak memindahkan atau menghapus posting apa pun.','Processing…'=>'Sedang diproses…','Provider'=>'Penyedia','Provider returned no text. Check the WordPress error log for the detailed failure reason.'=>'Penyedia tidak mengembalikan teks. Periksa log kesalahan WordPress untuk alasan kegagalan secara rinci.','Quality'=>'Kualitas','Quality (default — Sonnet / GPT-4o / Gemini Pro)'=>'Kualitas (default — Sonnet / GPT-4o / Gemini Pro)','Quality (Sonnet / GPT-4o / Gemini Pro)'=>'Kualitas (Soneta / GPT-4o / Gemini Pro)','Quality: used for post translation and content generation — higher quality, higher cost.'=>'Kualitas: digunakan untuk terjemahan posting dan pembuatan konten — kualitas lebih tinggi, biaya lebih tinggi.','Quick Translate'=>'Terjemahan Cepat','Quick Translation'=>'Terjemahan Cepat','Quick Translation is used for snippet/chunk mode — short passages translated on demand from the toolbar, editor, or block popovers. It uses a separate, lighter configuration from the full-page translation to keep responses fast and cost-effective.'=>'Terjemahan Cepat digunakan untuk mode potongan/fragmen — potongan pendek diterjemahkan sesuai permintaan dari toolbar, editor, atau popover blok. Menggunakan konfigurasi yang terpisah dan lebih ringan dari terjemahan halaman penuh untuk menjaga respons tetap cepat dan hemat biaya.','Re-enables Gutenberg\'s canLockBlocks. Useful for editorial templates that need to prevent contributors from moving or deleting specific blocks.'=>'Mengaktifkan kembali canLockBlocks Gutenberg. Berguna untuk template editorial yang perlu mencegah kontributor memindahkan atau menghapus blok tertentu.','Re-enables supportsTemplateMode. Core to Full-Site-Editing workflows where post-level template overrides are intentional.'=>'Mengaktifkan kembali supportsTemplateMode. Inti dari alur kerja Pengeditan Seluruh Situs di mana override template tingkat posting adalah sengaja.','Re-generates and updates the cached result.'=>'Menghasilkan ulang dan memperbarui hasil yang disimpan sementara.','Re-scan'=>'Pindai ulang','Re-scanning…'=>'Memindai ulang…','Re-translate'=>'Terjemahkan ulang','Redirect visitors to their preferred language based on the browser\'s Accept-Language header'=>'Alihkan pengunjung ke bahasa pilihan mereka berdasarkan header Accept-Language browser','Refine further — e.g. "make it shorter" or "use a formal tone"…'=>'Perbaiki lebih lanjut — misalnya "buat lebih singkat" atau "gunakan nada formal"…','Refine further:'=>'Perbaiki lebih lanjut:','Refinement'=>'Perbaikan','Refinement failed — please try again.'=>'Perbaikan gagal — silakan coba lagi.','Refining…'=>'Sedang memperbaiki…','Regenerates WordPress rewrite rules so URL prefixes, language-specific slugs, and archive rewrites are all in sync. Necessary after changing the primary language or adding new language support.'=>'Mengregenerasi ulang aturan penulisan ulang WordPress sehingga prefiks URL, slug khusus bahasa, dan penulisan ulang arsip semuanya sinkron. Diperlukan setelah mengubah bahasa utama atau menambahkan dukungan bahasa baru.','Remove stored key'=>'Hapus kunci yang disimpan','Report an issue on GitHub'=>'Laporkan masalah di GitHub','Request failed — please try again.'=>'Permintaan gagal — silakan coba lagi.','Request failed.'=>'Permintaan gagal.','Request failed. Check your connection.'=>'Permintaan gagal. Periksa koneksi Anda.','Request failed. Please try again.'=>'Permintaan gagal. Silakan coba lagi.','Requests'=>'Permintaan','Reset'=>'Reset','Result will appear here…'=>'Hasil akan muncul di sini…','Retranslate'=>'Terjemahkan ulang','Retranslating…'=>'Sedang menerjemahkan ulang…','Review carefully — links and slugs not updated.'=>'Periksa dengan cermat — tautan dan slug tidak diperbarui.','Review translation before applying'=>'Tinjau terjemahan sebelum menerapkan','Revise'=>'Revisi','Revision'=>'Revisi','Revision Type'=>'Jenis Revisi','Router'=>'Router','Router Tab'=>'Tab Router','Save Debug Setting'=>'Simpan Pengaturan Debug','Save Router Settings'=>'Simpan Pengaturan Router','Save Settings'=>'Simpan Pengaturan','Save the post to persist changes.'=>'Simpan posting untuk mempertahankan perubahan.','Save Uninstall Setting'=>'Simpan Pengaturan Uninstall','Saved to the meta description field when you apply.'=>'Disimpan ke bidang meta deskripsi saat Anda menerapkan.','Scan failed: '=>'Gagal memindai: ','Scan request failed. Please try again.'=>'Permintaan pemindaian gagal. Silakan coba lagi.','Scanning posts for broken language links…'=>'Memindai posting untuk tautan bahasa yang rusak…','Search'=>' Cari','Search Results'=>' Hasil Pencarian','Security check failed — file path is not permitted.'=>'Gagal pemeriksaan keamanan — jalur file tidak diizinkan.','Select a language to manage its FSE templates, template parts, and navigation menus.'=>'Pilih bahasa untuk mengelola template FSE, bagian template, dan menu navigasi.','Select language'=>'Pilih bahasa','SEO character-count info'=>'Informasi jumlah karakter SEO','Server setup (subdomain)'=>'Pengaturan server (subdomain)','Sets the default AI behaviour for all features site-wide. Individual posts can override this for Translation and Content Generation via the Lingua Forge meta box.'=>'Mengatur perilaku AI default untuk semua fitur di seluruh situs. Postingan individual dapat mengesampinginya untuk Terjemahan dan Pembuatan Konten melalui kotak meta Lingua Forge.','Settings'=>'Pengaturan','Settings saved.'=>'Pengaturan disimpan.','Show home link'=>'Tampilkan tautan beranda','Shown when no translation exists for the visitor\'s language.'=>'Ditampilkan saat tidak ada terjemahan untuk bahasa pengunjung.','Single'=>' Tunggal','Single %s'=>' %s Tunggal','Single: %s'=>' Tunggal: %s','Site-wide ceiling on AI requests per UTC day (counts both Toolbar translations and block revisions). Counter resets at UTC midnight. Set to 0 to disable the cap.'=>'Batas atas permintaan AI di seluruh situs per hari UTC (menghitung terjemahan Toolbar dan revisi blok). Penghitung direset pada tengah malam UTC. Atur ke 0 untuk menonaktifkan batas.','Size'=>'Ukuran','Some link fixes failed.'=>'Beberapa perbaikan tautan gagal.','Some nav ref fixes failed.'=>'Beberapa perbaikan referensi navigasi gagal.','Some part fixes failed.'=>'Beberapa perbaikan bagian gagal.','Some parts could not be created.'=>'Beberapa bagian tidak dapat dibuat.','Some templates could not be created.'=>'Beberapa template tidak dapat dibuat.','Some translations failed.'=>'Beberapa terjemahan gagal.','Source file not found.'=>'File sumber tidak ditemukan.','Source lang'=>'Bahasa sumber','Source language'=>'Bahasa sumber','Source term'=>'Istilah sumber','Standard'=>'Standar','Standard uses each feature\'s own tuned temperature: Translation T=0.2 (precise), Quick Translate T=0.4, Content Generator T=0.6 (creative). The other presets apply a single fixed temperature across all features.'=>'Standar menggunakan suhu yang disesuaikan untuk setiap fitur: Terjemahan T=0.2 (tepat), Terjemahan Cepat T=0.4, Pembuat Konten T=0.6 (kreatif). Preset lainnya menerapkan suhu tetap tunggal di semua fitur.','Status'=>'Status','Status / Actions'=>'Status / Tindakan','Storytelling'=>' Bercerita','Strict-preservation mode for legal, regulatory, medical, or technical content. When on, every AI feature uses a low sampling temperature and appends the addendum below to its system prompt — terminology, article numbers, units, brand names, and regulatory language are preserved verbatim rather than paraphrased.'=>'Mode pelestarian ketat untuk konten hukum, regulasi, medis, atau teknis. Saat aktif, setiap fitur AI menggunakan suhu sampling rendah dan menambahkan addendum di bawah ke prompt sistemnya — terminologi, nomor artikel, satuan, nama merek, dan bahasa regulasi dipertahankan secara verbatim daripada diparafrasekan.','Structured Outline'=>'Garis besar terstruktur','Subdomain mode requires your web server to point all language subdomains (e.g. de.example.com) to this WordPress installation. After switching modes, flush permalink rules and clear any caches. If your home URL includes www (e.g. www.example.com), use the lf_base_domain filter to set the bare apex domain so subdomains are constructed correctly.'=>'Mode subdomain memerlukan server web Anda untuk menunjuk semua subdomain bahasa (misalnya de.example.com) ke instalasi WordPress ini. Setelah beralih mode, bersihkan aturan permalink dan hapus cache apa pun. Jika URL beranda Anda menyertakan www (misalnya www.example.com), gunakan filter lf_base_domain untuk mengatur domain puncak agar subdomain dibangun dengan benar.','Subdomain — de.example.com/'=>'Subdomain — de.example.com/','Supported providers: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Only one provider is active at a time. Select the active provider on the General tab.'=>'Penyedia yang didukung: Anthropic (Claude), OpenAI (GPT), Google (Gemini). Hanya satu penyedia yang aktif pada satu waktu. Pilih penyedia aktif di tab Umum.','T=%s'=>'T=%s','T=0.2–0.6, per feature'=>'T=0.2–0.6, per fitur','Target lang'=>'Bahasa target','Target Language'=>'Bahasa Target','Target language'=>'Bahasa target','Target term'=>'Istilah target','Target: 140–160 chars for optimal SERP display'=>'Target: 140–160 karakter untuk tampilan SERP yang optimal','Technical'=>' Teknis','Technical / Scientific'=>'Teknis / Ilmiah','Technical / Scientific instructions'=>'Instruksi Teknis / Ilmiah','Template "%s" already exists.'=>'"%s" sudah ada.','Template "{expected}" does not exist — create it in the Site Editor first.'=>'Template "{expected}" tidak ada — buat terlebih dahulu di Editor Situs.','Template has no content.'=>' Template tidak memiliki konten.','Template mode'=>'Mode template','Template not found or not stored in the database.'=>' Template tidak ditemukan atau tidak disimpan dalam database.','Template part "%s" already exists.'=>' Bagian template "%s" sudah ada.','Template part has no content.'=>' Bagian template tidak memiliki konten.','Template part not found or not stored in the database.'=>' Bagian template tidak ditemukan atau tidak disimpan dalam database.','Template Parts'=>'Bagian Template','Templates'=>'Template','Test connection'=>'Uji koneksi','Testing…'=>'Sedang pengujian…','Text domain / locale'=>'Domain teks / lokal','Text to translate'=>'Teks untuk diterjemahkan','The API Response Cache stores the raw result of every AI request — translation, meta description, excerpt, and content generation — keyed by a hash of the inputs (content, language pair, provider, model). Subsequent requests with identical inputs are served from the cache with no API call. The cache is different from Translation Memory: Translation Memory operates at the block level and is shared across posts; the API Response Cache operates at the feature level and is keyed per post.'=>'Cache Respons API menyimpan hasil mentah dari setiap permintaan AI — terjemahan, deskripsi meta, kutipan, dan pembuatan konten — berdasarkan hash dari input (konten, pasangan bahasa, penyedia, model). Permintaan berikutnya dengan input yang sama disajikan dari cache tanpa panggilan API. Cache ini berbeda dari Memori Terjemahan: Memori Terjemahan beroperasi di tingkat blok dan dibagikan antar posting; Cache Respons API beroperasi di tingkat fitur dan dikunci per posting.','The editor did not accept the content — please try again.'=>'Editor tidak menerima konten — silakan coba lagi.','The Light tier uses the fast model configured in the Models table above (default: Haiku / Flash). Switch to Quality if you need the same translation accuracy as full-page mode for snippets.'=>'Tier Light menggunakan model cepat yang dikonfigurasi dalam tabel Model di atas (default: Haiku / Flash). Beralih ke Kualitas jika Anda membutuhkan tingkat akurasi terjemahan yang sama seperti mode halaman penuh untuk potongan.','The phrase as it appears in the source text.'=>'Frasa seperti yang muncul dalam teks sumber.','The primary language is always served at the root of your site — no URL prefix in path mode, no language subdomain in subdomain mode. All other languages use either a /lang/ path prefix (e.g. example.com/de/) or a language subdomain (e.g. de.example.com), depending on the URL structure setting below.'=>'Bahasa utama selalu disajikan di akar situs Anda — tanpa prefix URL dalam mode path, tanpa subdomain bahasa dalam mode subdomain. Semua bahasa lain menggunakan prefix path /lang/ (misalnya example.com/de/) atau subdomain bahasa (misalnya de.example.com), tergantung pengaturan struktur URL di bawah.','The source page has no footnotes.'=>'Halaman sumber tidak memiliki catatan kaki.','The upload failed — please try again.'=>'Unggahan gagal — silakan coba lagi.','These footnotes come from the source page and are shown here for reference only. Add them to this page using the block editor.'=>'Catatan kaki ini berasal dari halaman sumber dan ditampilkan di sini hanya untuk referensi. Tambahkan ke halaman ini menggunakan editor blok.','This is the source page. Footnotes are edited directly in the block editor.'=>'Ini adalah halaman sumber. Catatan kaki diedit langsung di editor blok.','This key is currently supplied by a server %s and cannot be removed here. Enter a new key above to override it with a database value.'=>'Kunci ini saat ini disediakan oleh server %s dan tidak dapat dihapus di sini. Masukkan kunci baru di atas untuk menggantinya dengan nilai dari basis data.','Tip: to reset a model to the built-in default, clear the field and save.'=>'Tip: untuk mengatur ulang model ke default bawaan, hapus isian dan simpan.','To use a custom encryption secret (instead of the derived wp_salt value), add this to wp-config.php:'=>'Untuk menggunakan rahasia enkripsi khusus (alih-alih nilai wp_salt yang diambil dari), tambahkan ini ke wp-config.php:','Today'=>'Hari ini','Token consumption rolled up by feature, provider, and model. Recorded on every successful AI call; Test Connection pings are deliberately excluded so they don\'t skew the totals. The underlying table aggregates daily — pick a window below to view it.'=>'Penggunaan token yang dikumpulkan berdasarkan fitur, penyedia, dan model. Dicatat pada setiap panggilan AI yang berhasil; ping Uji Koneksi secara sengaja dikecualikan agar tidak mempengaruhi total. Tabel dasar mengagregasi harian — pilih jendela di bawah untuk melihatnya.','Tone'=>'Nada','tone'=>'Nada','Tone:'=>'Nada:','Too many AI requests. Please retry in %d seconds.'=>'Permintaan AI terlalu banyak. Silakan coba lagi dalam %d detik.','Total'=>'Total','Total tokens'=>'Total token','Translate'=>'Terjemahkan','Translate / Revise'=>'Terjemahkan / Revisi','Translate / Revise block'=>'Blok terjemahan / Revisi','Translate all'=>'Terjemahkan semua','Translate chunk'=>'Terjemahkan bagian','Translate Content'=>'Terjemahkan Konten','Translate missing'=>'Terjemahan hilang','Translate page…'=>'Terjemahkan halaman…','Translated content'=>'Isi terjemahan','Translated Names'=>'Nama yang Diterjemahkan','Translated title'=>'Judul terjemahan','Translated to:'=>'Diterjemahkan ke:','Translated. Review in the Site Editor — internal links, navigation URLs, and template slugs are not updated automatically.'=>'Diterjemahkan. Tinjau di Editor Situs — tautan internal, URL navigasi, dan slug template tidak diperbarui secara otomatis.','Translating…'=>'Sedang menerjemahkan…','Translation'=>'Terjemahan','Translation Caching'=>'Caching Terjemahan','Translation found but permalink could not be generated'=>'Terjemahan ditemukan tetapi permalink tidak dapat dibuat','Translation Limits'=>'Batasan Terjemahan','Translation Limits & Behavior'=>'Batas & Perilaku Terjemahan','Translation Limits: control which user roles can trigger AI translation, and set a monthly token budget. Exceeding the budget suspends AI calls until the month resets.'=>'Batas Terjemahan: mengontrol peran pengguna mana yang dapat memicu terjemahan AI, dan menetapkan anggaran token bulanan. Melebihi anggaran akan menangguhkan panggilan AI sampai bulan berikutnya.','Translation Memory'=>'Memori Terjemahan','Translation Memory caches AI results by content hash, language pair, provider, and model. Editing a post invalidates the cache entry so the next translate call gets a fresh result.'=>'Memori Terjemahan menyimpan hasil AI berdasarkan hash konten, pasangan bahasa, penyedia, dan model. Mengedit sebuah postingan akan membatalkan cache sehingga panggilan terjemahan berikutnya mendapatkan hasil yang baru.','Translation Memory cleared. %d cached block was removed.'=>'Memori Terjemahan dibersihkan. %d blok yang di-cache dihapus.' . "\0" . '','Translation Memory: stores the full translated post per content hash. Clear it when you want to force a retranslation of all posts regardless of whether their content changed.'=>'Memori Terjemahan: menyimpan seluruh postingan yang telah diterjemahkan berdasarkan hash konten. Bersihkan jika Anda ingin memaksa terjemahan ulang semua postingan tanpa mempedulikan apakah kontennya berubah.','Translation workflow'=>'Alur kerja terjemahan','Translation, Content Generator'=>'Terjemahan, Pembuat Konten','Type'=>'Jenis','Uli Hake'=>'Uli Hake','Uninstall Behaviour'=>'Penghapusan Perilaku','Uninstall setting saved.'=>'Pengaturan penghapusan disimpan.','unknown error'=>'kesalahan tidak diketahui','Unknown provider.'=>'Penyedia tidak dikenal.','Up'=>'Atas','Upload .mo file'=>'Unggah file .mo','Upload compiled .mo files to override third-party plugin strings for specific locales — for example, a custom VikBooking translation that uses "apartment" instead of "room". Files must follow the WordPress naming convention: {textdomain}-{locale}.mo (e.g. vikbooking-ca.mo). They are stored in the uploads folder and survive plugin updates.'=>'Unggah file .mo yang dikompilasi untuk menimpa string plugin pihak ketiga untuk lokal tertentu — misalnya, terjemahan VikBooking khusus yang menggunakan "apartemen" alih-alih "kamar". File harus mengikuti konvensi penamaan WordPress: {textdomain}-{locale}.mo (misalnya vikbooking-ca.mo). Mereka disimpan di folder unggahan dan tetap ada setelah pembaruan plugin.','Upload Override'=>'Unggah Penimpa','URL could not be mapped to a post — check the link target exists'=>'URL tidak dapat dipetakan ke posting — periksa apakah target tautan ada','URL structure'=>'Struktur URL','URL structure: path-prefix mode (example.com/de/) requires no server changes. Subdomain mode (de.example.com) requires a wildcard DNS record, a wildcard SSL certificate, and a web server configuration change — see the Server Setup guide.'=>'Struktur URL: mode awalan jalur (example.com/de/) tidak memerlukan perubahan server. Mode subdomain (de.example.com) memerlukan catatan DNS wildcard, sertifikat SSL wildcard, dan perubahan konfigurasi server web — lihat panduan Pengaturan Server.','Use the tabs across the top of this page to configure each area. Changes to the Router tab take effect immediately; changes to AI keys and model settings apply to the next AI request.'=>'Gunakan tab di bagian atas halaman ini untuk mengonfigurasi setiap area. Perubahan pada tab Router berlaku segera; perubahan pada kunci AI dan pengaturan model berlaku untuk permintaan AI berikutnya.','User-managed terminology table per language pair. Entries are appended to the translation system prompt so the AI uses preferred terms consistently — critical for domain vocabulary ("kWp", "PPA", "interconnection point"), brand names that must not translate, and standardised regulatory phrasing. Both language fields are optional: leave "Source language" blank to apply the entry regardless of which language you are translating from; leave "Target language" blank to apply it to all target languages at once.'=>'Tabel terminologi yang dikelola pengguna per pasangan bahasa. Entri ditambahkan ke prompt sistem terjemahan agar AI menggunakan istilah yang disukai secara konsisten — penting untuk kosakata domain ("kWp", "PPA", "titik interkoneksi"), nama merek yang tidak boleh diterjemahkan, dan frasa regulasi yang distandarisasi. Kedua bidang bahasa bersifat opsional: tinggalkan "Bahasa sumber" kosong untuk menerapkan entri tanpa memandang bahasa asal; tinggalkan "Bahasa target" kosong untuk menerapkannya ke semua bahasa target sekaligus.','Using custom meta description.'=>'Menggunakan meta deskripsi khusus.','View'=>'Lihat','View built-in default'=>'Lihat default bawaan','View details'=>'Lihat detail','View Lingua Forge details'=>'Lihat detail Lingua Forge','Visit plugin site'=>'Kunjungi situs plugin','Warning:'=>'Peringatan:','When debug logging is enabled (via the toggle below or by defining LINGUAFORGE_AI_DEBUG in wp-config.php), the Translation and FSE template translation features write their raw AI prompts and responses to disk for troubleshooting. Use this section to monitor that output and clear it once you have what you need — the files can grow quickly on large pages. Configure the destination directory via the linguaforge_debug_dir filter.'=>'Ketika pencatatan debug diaktifkan (melalui toggle di bawah atau dengan mendefinisikan LINGUAFORGE_AI_DEBUG di wp-config.php), fitur terjemahan dan template FSE menulis prompt AI mentah dan responsnya ke disk untuk pemecahan masalah. Gunakan bagian ini untuk memantau output tersebut dan bersihkan setelah Anda mendapatkan apa yang Anda butuhkan — file dapat tumbuh dengan cepat di halaman besar. Konfigurasikan direktori tujuan melalui filter linguaforge_debug_dir.','When enabled, first-time visitors with no language cookie and no language prefix in the URL are redirected to the closest matching language version. The redirect is skipped if the browser\'s preferred language is not among the active router languages. Once a visitor selects a language via the switcher, the cookie takes priority and the browser header is ignored on all future visits.'=>'Jika diaktifkan, pengunjung pertama kali yang tidak memiliki cookie bahasa dan tidak memiliki prefix bahasa di URL akan dialihkan ke versi bahasa yang paling cocok. Pengalihan dilewati jika bahasa yang dipilih browser tidak termasuk dalam bahasa router aktif. Setelah pengunjung memilih bahasa melalui switcher, cookie menjadi prioritas dan header browser diabaikan pada kunjungan berikutnya.','Which model tier to use for full-page translation. Quality uses the model configured in the Models table above and is recommended for accurate, long-form translation. Switch to Light only if speed or cost is the priority and the content is short.'=>'Tingkat model mana yang digunakan untuk terjemahan halaman penuh. Kualitas menggunakan model yang dikonfigurasi dalam tabel Model di atas dan disarankan untuk terjemahan yang akurat dan panjang. Beralih ke Ringan hanya jika kecepatan atau biaya adalah prioritas dan kontennya singkat.','WP-CLI reference'=>'Referensi WP-CLI','Write AI prompts and responses to disk for troubleshooting'=>'Tulis prompt AI dan respons ke disk untuk pemecahan masalah','You can also define keys as constants or environment variables (e.g. in wp-config.php). Those sources are used automatically as a fallback when no database key is stored.'=>'Anda juga dapat mendefinisikan kunci sebagai konstanta atau variabel lingkungan (misalnya di wp-config.php). Sumber-sumber tersebut digunakan secara otomatis sebagai cadangan jika tidak ada kunci database yang disimpan.','You do not have permission to manage these settings.'=>'Anda tidak memiliki izin untuk mengelola pengaturan ini.','You do not have permission to read this post.'=>'Anda tidak memiliki izin untuk membaca posting ini.','{n} stale path(s)'=>'{n} jalur usang','— Any source language —'=>'— Sumber apa saja —','— Any target language —'=>'— Bahasa target apa saja —','— Any target —'=>'— Target apa saja —','— Any —'=>'— Apa saja —','— auto-detect —'=>'— deteksi otomatis —','— select a language —'=>'— pilih bahasa —','— toggle in Settings → Behavior.'=>'— toggle di Pengaturan → Perilaku.','← Back'=>'← Kembali','↑ Detected from current post'=>'↑ Terdeteksi dari posting saat ini','↺ Re-translate'=>'↺ Terjemahkan ulang','↺ Refine'=>'↺ Perbaiki','↺ Refresh'=>'↺ Segarkan','↺ Refreshing…'=>'↺ Memuat ulang…','⚠ Borderline'=>'⚠ Batas','⚠ No <strong>{lang}</strong> posts found. Make sure all translated posts have their Language meta set to <strong>{lang}</strong> in the Language metabox.'=>'⚠ Tidak ditemukan posting <strong>{lang}</strong>. Pastikan semua posting yang diterjemahkan memiliki meta Bahasa yang diatur ke <strong>{lang}</strong> di kotak meta Bahasa.','⚠ No changes'=>'⚠ Tidak ada perubahan','⚠ No changes — re-scan?'=>'⚠ Tidak ada perubahan — pemindaian ulang?','✅ Fixed ({n})'=>'✅ Diperbaiki ({n})','✅ No broken links or template mismatches found for <strong>{lang}</strong>. Scanned <strong>{scanned}</strong> post(s) and page(s) — all checks passed. Template part links (header, footer, sidebar) are not included here — use the Fix Template Parts button to check those separately.'=>'✅ Tidak ditemukan tautan rusak atau ketidakcocokan template untuk <strong>{lang}</strong>. Memindai <strong>{scanned}</strong> posting dan halaman — semua pemeriksaan lolos. Tautan bagian template (header, footer, sidebar) tidak termasuk di sini — gunakan tombol Perbaiki Bagian Template untuk memeriksa secara terpisah.','✅ Template fixed'=>'✅ Template diperbaiki','✓ All parts created.'=>'✓ Semua bagian dibuat.','✓ All templates created.'=>'✓ Semua template dibuat.','✓ All translated.'=>'✓ Semuanya diterjemahkan.','✓ Configured'=>'✓ Dikonfigurasi','✓ Connection OK'=>'✓ Koneksi OK','✓ Content generated — see the overlay to review, refine, and apply.'=>'✓ Konten telah dibuat — lihat lapisan untuk meninjau, menyempurnakan, dan menerapkan.','✓ Done'=>'✓ Selesai','✓ Enabled'=>'✓ Diaktifkan','✓ Good length'=>'✓ Panjang yang baik','✓ In safe storage'=>'✓ Disimpan di penyimpanan aman','✓ Language installed.'=>'✓ Bahasa terinstal.','✓ Links fixed.'=>'✓ Tautan diperbaiki.','✓ Nav refs fixed.'=>'✓ Referensi navigasi diperbaiki.','✓ Parts fixed.'=>'✓ Bagian diperbaiki.','✓ Pattern translated.'=>'✓ Pola diterjemahkan.','✓ Refined — review the updated draft above.'=>'✓ Diperbaiki — tinjau draf yang diperbarui di atas.','✓ Translation saved'=>'✓ Terjemahan disimpan','✗ Disabled'=>'✗ Dinonaktifkan','✗ Error:'=>'✗ Kesalahan:','✗ Failed:'=>'✗ Gagal:','✗ Not configured'=>'✗ Tidak dikonfigurasi','✗ Too long'=>'✗ Terlalu panjang','✗ Too short'=>'✗ Terlalu pendek','❌ Failed'=>'❌ Gagal','📄 Wrong template'=>'📄 Template yang salah','📍 Stale path (page moved)'=>'📍 Jalur usang (halaman dipindahkan)']];
